import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { api } from "@/lib/api";

export function useBoqs(projectId: string, page = 1, pageSize = 20) {
  return useQuery({
    queryKey: ["boqs", projectId, page, pageSize],
    queryFn: () => api.listBoqs(projectId, { page, page_size: pageSize }),
  });
}

export function useBoq(boqId: string) {
  return useQuery({
    queryKey: ["boq", boqId],
    queryFn: () => api.getBoq(boqId),
    enabled: !!boqId,
  });
}

export function useBoqItems(boqId: string, page = 1, pageSize = 100) {
  return useQuery({
    queryKey: ["boqItems", boqId, page, pageSize],
    queryFn: () => api.getBoqItems(boqId, { page, page_size: pageSize }),
    enabled: !!boqId,
  });
}

export function useUploadBoq() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ projectId, file, notes }: { projectId: string; file: File; notes?: string }) =>
      api.uploadBoq(projectId, file, notes),
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: ["boqs", variables.projectId] });
    },
  });
}

export function useDeleteBoq() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ id, projectId }: { id: string; projectId: string }) =>
      api.deleteBoq(id).then(() => ({ projectId })),
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: ["boqs", variables.projectId] });
    },
  });
}

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { api } from "@/lib/api";

export function useQuotes(projectId: string, page = 1, pageSize = 20) {
  return useQuery({
    queryKey: ["quotes", projectId, page, pageSize],
    queryFn: () => api.listQuotes(projectId, { page, page_size: pageSize }),
  });
}

export function useQuote(quoteId: string) {
  return useQuery({
    queryKey: ["quote", quoteId],
    queryFn: () => api.getQuote(quoteId),
    enabled: !!quoteId,
  });
}

export function useCreateQuote() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({
      projectId,
      data,
    }: {
      projectId: string;
      data: {
        boq_id: string;
        markup_percent?: number;
        tax_percent?: number;
        terms?: string;
        validity_days?: number;
      };
    }) => api.createQuote(projectId, data),
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: ["quotes", variables.projectId] });
    },
  });
}

export function useUpdateQuote() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ id, data }: { id: string; data: Partial<import("@/types/api").Quote> }) =>
      api.updateQuote(id, data),
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: ["quote", variables.id] });
    },
  });
}

export function useDeleteQuote() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ id, projectId }: { id: string; projectId: string }) =>
      api.deleteQuote(id).then(() => ({ projectId })),
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: ["quotes", variables.projectId] });
    },
  });
}

export function useSubmitQuote() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: api.submitQuote,
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ["quote", data.id] });
      queryClient.invalidateQueries({ queryKey: ["quotes", data.project_id] });
    },
  });
}

export function useApproveQuote() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: api.approveQuote,
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ["quote", data.id] });
      queryClient.invalidateQueries({ queryKey: ["quotes", data.project_id] });
    },
  });
}

export function useSendQuote() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: api.sendQuote,
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ["quote", data.id] });
      queryClient.invalidateQueries({ queryKey: ["quotes", data.project_id] });
    },
  });
}

export function useRespondQuote() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({
      id,
      data,
    }: {
      id: string;
      data: { response: "accepted" | "rejected"; notes?: string };
    }) => api.respondQuote(id, data),
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ["quote", data.id] });
      queryClient.invalidateQueries({ queryKey: ["quotes", data.project_id] });
    },
  });
}

export function useCloneQuote() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ id, projectId }: { id: string; projectId: string }) =>
      api.cloneQuote(id).then((quote) => ({ quote, projectId })),
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: ["quotes", variables.projectId] });
    },
  });
}

import { useState } from "react";
import { useUploadBoq } from "@/hooks/useBoqs";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Upload } from "lucide-react";

interface BOQUploadProps {
  projectId: string;
  onSuccess?: () => void;
}

export function BOQUpload({ projectId, onSuccess }: BOQUploadProps) {
  const [file, setFile] = useState<File | null>(null);
  const [notes, setNotes] = useState("");
  const uploadMutation = useUploadBoq();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!file) return;
    await uploadMutation.mutateAsync({ projectId, file, notes: notes || undefined });
    setFile(null);
    setNotes("");
    onSuccess?.();
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle>Upload BOQ</CardTitle>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="boq-file">BOQ File (.xlsx or .json)</Label>
            <input
              id="boq-file"
              type="file"
              accept=".xlsx,.json"
              onChange={(e) => setFile(e.target.files?.[0] ?? null)}
              className="block w-full text-sm file:mr-4 file:rounded-md file:border-0 file:bg-primary file:px-4 file:py-2 file:text-primary-foreground hover:file:bg-primary/90"
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="boq-notes">Notes (optional)</Label>
            <Textarea
              id="boq-notes"
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              placeholder="Add any notes about this BOQ version..."
              rows={3}
            />
          </div>
          <Button type="submit" disabled={!file || uploadMutation.isPending}>
            <Upload className="mr-2 h-4 w-4" />
            {uploadMutation.isPending ? "Uploading..." : "Upload BOQ"}
          </Button>
          {uploadMutation.isError && (
            <p className="text-sm text-destructive">Upload failed. Please try again.</p>
          )}
        </form>
      </CardContent>
    </Card>
  );
}

import { useState } from "react";
import { useBoqs, useDeleteBoq } from "@/hooks/useBoqs";
import { Button } from "@/components/ui/button";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Eye, Trash2, ChevronLeft, ChevronRight } from "lucide-react";

interface BOQVersionListProps {
  projectId: string;
  onViewItems: (boqId: string) => void;
}

export function BOQVersionList({ projectId, onViewItems }: BOQVersionListProps) {
  const [page, setPage] = useState(1);
  const pageSize = 10;
  const { data, isLoading } = useBoqs(projectId, page, pageSize);
  const deleteMutation = useDeleteBoq();

  const handleDelete = (id: string) => {
    if (confirm("Delete this BOQ version? This cannot be undone.")) {
      deleteMutation.mutate({ id, projectId });
    }
  };

  if (isLoading) return <div className="p-4 text-muted-foreground">Loading BOQs...</div>;

  const items = data?.items ?? [];
  const total = data?.total ?? 0;
  const totalPages = Math.ceil(total / pageSize);

  return (
    <Card>
      <CardHeader>
