  const handleClone = (id: string) => {
    cloneMutation.mutate({ id, projectId });
  };

  if (isLoading) return <div className="p-4 text-muted-foreground">Loading quotes...</div>;

  const items = data?.items ?? [];
  const total = data?.total ?? 0;
