                          {quote.status === "draft" && (user?.role === "admin" || user?.role === "pm") && (
                            <Button
                              variant="ghost"
                              size="icon"
                              onClick={() => handleDelete(quote.id)}
                              disabled={deleteMutation.isPending}
                            >
                              <Trash2 className="h-4 w-4 text-destructive" />
                            </Button>
                          )}
                        </div>
                      </TableCell>
                    </TableRow>
