import { useState } from "react";
import { useBoqs, useBoqItems } from "@/hooks/useBoqs";
import { useCreateQuote } from "@/hooks/useQuotes";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";

interface QuoteBuilderProps {
  projectId: string;
  onSuccess?: () => void;
  onCancel?: () => void;
}

export function QuoteBuilder({ projectId, onSuccess, onCancel }: QuoteBuilderProps) {
  const [selectedBoqId, setSelectedBoqId] = useState("");
  const [markupPercent, setMarkupPercent] = useState(15);
  const [taxPercent, setTaxPercent] = useState(18);
  const [terms, setTerms] = useState("");
  const [validityDays, setValidityDays] = useState(30);
  const [editableRates, setEditableRates] = useState<Record<string, number>>({});

  const { data: boqsData, isLoading: boqsLoading } = useBoqs(projectId, 1, 100);
  const { data: boqItemsData, isLoading: itemsLoading } = useBoqItems(selectedBoqId);
  const createMutation = useCreateQuote();

  const boqs = boqsData?.items ?? [];
  const rawItems = boqItemsData?.items ?? [];

  const items = rawItems.map((item) => ({
    ...item,
    rate: editableRates[item.id] ?? item.rate,
    amount: (editableRates[item.id] ?? item.rate) * item.quantity,
  }));

  const subtotal = items.reduce((sum, item) => sum + item.amount, 0);
  const markupAmount = subtotal * (markupPercent / 100);
  const afterMarkup = subtotal + markupAmount;
  const taxAmount = afterMarkup * (taxPercent / 100);
  const totalAmount = afterMarkup + taxAmount;

  const handleRateChange = (itemId: string, value: string) => {
    const num = parseFloat(value);
    if (!isNaN(num) && num >= 0) {
      setEditableRates((prev) => ({ ...prev, [itemId]: num }));
    }
  };

  const handleCreate = async () => {
    if (!selectedBoqId) return;
    await createMutation.mutateAsync({
      projectId,
      data: {
        boq_id: selectedBoqId,
        markup_percent: markupPercent,
        tax_percent: taxPercent,
        terms: terms || undefined,
        validity_days: validityDays,
      },
    });
    onSuccess?.();
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle>Create Quote</CardTitle>
      </CardHeader>
      <CardContent className="space-y-6">
        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <Label>BOQ Version</Label>
            <Select value={selectedBoqId} onValueChange={setSelectedBoqId}>
              <SelectTrigger>
                <SelectValue placeholder={boqsLoading ? "Loading..." : "Select BOQ version"} />
              </SelectTrigger>
              <SelectContent>
                {boqs.map((boq) => (
                  <SelectItem key={boq.id} value={boq.id}>
                    v{boq.version_number} — {boq.file_name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div className="space-y-2">
            <Label>Validity (days)</Label>
            <Input
              type="number"
              value={validityDays}
              onChange={(e) => setValidityDays(parseInt(e.target.value) || 30)}
              min={1}
            />
          </div>
          <div className="space-y-2">
            <Label>Markup %</Label>
            <Input
              type="number"
              value={markupPercent}
              onChange={(e) => setMarkupPercent(parseFloat(e.target.value) || 0)}
              min={0}
              step={0.5}
            />
          </div>
          <div className="space-y-2">
            <Label>Tax %</Label>
            <Input
              type="number"
              value={taxPercent}
              onChange={(e) => setTaxPercent(parseFloat(e.target.value) || 0)}
              min={0}
              step={0.5}
            />
          </div>
        </div>

        <div className="space-y-2">
          <Label>Terms & Conditions</Label>
          <Textarea
            value={terms}
            onChange={(e) => setTerms(e.target.value)}
            placeholder="Payment terms, warranty, delivery conditions..."
            rows={3}
          />
        </div>

        {selectedBoqId && (
          <>
            {itemsLoading ? (
              <div className="p-4 text-muted-foreground">Loading BOQ items...</div>
            ) : (
              <div className="space-y-2">
                <Label>Line Items (edit rates as needed)</Label>
                <div className="max-h-[400px] overflow-auto border rounded-md">
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>Line</TableHead>
                        <TableHead>Description</TableHead>
                        <TableHead>Unit</TableHead>
                        <TableHead className="text-right">Qty</TableHead>
                        <TableHead className="text-right w-32">Rate</TableHead>
                        <TableHead className="text-right">Amount</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {items.map((item) => (
                        <TableRow key={item.id}>
                          <TableCell className="font-mono">{item.line_number}</TableCell>
                          <TableCell>{item.description}</TableCell>
                          <TableCell>{item.unit}</TableCell>
                          <TableCell className="text-right">{item.quantity}</TableCell>
                          <TableCell className="text-right">
                            <Input
                              type="number"
                              value={item.rate}
                              onChange={(e) => handleRateChange(item.id, e.target.value)}
                              className="h-8 w-32 text-right"
                              min={0}
                            />
                          </TableCell>
                          <TableCell className="text-right">₹{item.amount.toLocaleString()}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
              </div>
            )}

            <Card className="bg-muted/50">
              <CardContent className="p-4 space-y-2">
                <div className="flex justify-between text-sm">
                  <span>Subtotal</span>
                  <span>₹{subtotal.toLocaleString()}</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span>Markup ({markupPercent}%)</span>
                  <span>₹{markupAmount.toLocaleString()}</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span>Tax ({taxPercent}%)</span>
                  <span>₹{taxAmount.toLocaleString()}</span>
                </div>
                <div className="flex justify-between font-semibold border-t pt-2">
                  <span>Total</span>
                  <span>₹{totalAmount.toLocaleString()}</span>
                </div>
              </CardContent>
            </Card>
          </>
        )}

        <div className="flex gap-2">
          <Button onClick={handleCreate} disabled={!selectedBoqId || createMutation.isPending}>
            {createMutation.isPending ? "Creating..." : "Create Quote"}
          </Button>
          {onCancel && (
            <Button variant="outline" onClick={onCancel}>
              Cancel
            </Button>
          )}
        </div>
        {createMutation.isError && (
          <p className="text-sm text-destructive">Failed to create quote.</p>
        )}
      </CardContent>
    </Card>
  );
}

import { useCurrentUser } from "@/hooks/useAuth";
import { useSubmitQuote, useApproveQuote, useSendQuote, useRespondQuote } from "@/hooks/useQuotes";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import type { QuoteStatus } from "@/types/api";

interface QuoteActionsProps {
  quoteId: string;
  status: QuoteStatus;
  onAction?: () => void;
}

const STATUS_CONFIG: Record<QuoteStatus, { label: string; className: string }> = {
  draft: { label: "Draft", className: "bg-gray-100 text-gray-800" },
  pending_approval: { label: "Pending Approval", className: "bg-yellow-100 text-yellow-800" },
  approved: { label: "Approved", className: "bg-blue-100 text-blue-800" },
  sent: { label: "Sent", className: "bg-purple-100 text-purple-800" },
  accepted: { label: "Accepted", className: "bg-green-100 text-green-800" },
  rejected: { label: "Rejected", className: "bg-red-100 text-red-800" },
};

export function QuoteActions({ quoteId, status, onAction }: QuoteActionsProps) {
  const { data: user } = useCurrentUser();
  const submitMutation = useSubmitQuote();
  const approveMutation = useApproveQuote();
  const sendMutation = useSendQuote();
  const respondMutation = useRespondQuote();

  const isAdminOrPm = user?.role === "admin" || user?.role === "pm";

  const handleAction = async (action: () => Promise<unknown>) => {
    await action();
    onAction?.();
  };

  const buttons: React.ReactNode[] = [];

  if (status === "draft" && isAdminOrPm) {
    buttons.push(
      <Button
        key="submit"
        onClick={() => handleAction(() => submitMutation.mutateAsync(quoteId))}
        disabled={submitMutation.isPending}
      >
        Submit for Approval
      </Button>
    );
  }

  if (status === "pending_approval" && user?.role === "admin") {
    buttons.push(
      <Button
        key="approve"
        onClick={() => handleAction(() => approveMutation.mutateAsync(quoteId))}
        disabled={approveMutation.isPending}
      >
        Approve
      </Button>
    );
    buttons.push(
      <Button
        key="reject-draft"
        variant="outline"
        onClick={() => handleAction(() =>
          respondMutation.mutateAsync({
            id: quoteId,
            data: { response: "rejected", notes: "Rejected — sent back to draft" },
          })
        )}
        disabled={respondMutation.isPending}
      >
        Reject to Draft
      </Button>
    );
  }

  if (status === "approved" && isAdminOrPm) {
    buttons.push(
      <Button
        key="send"
        onClick={() => handleAction(() => sendMutation.mutateAsync(quoteId))}
        disabled={sendMutation.isPending}
      >
        Send to Client
      </Button>
    );
  }

  if (status === "sent" && isAdminOrPm) {
    buttons.push(
      <Button
        key="accept"
        onClick={() => handleAction(() =>
          respondMutation.mutateAsync({ id: quoteId, data: { response: "accepted" } })
        )}
        disabled={respondMutation.isPending}
        className="bg-green-600 hover:bg-green-700"
      >
        Record: Accepted
      </Button>
    );
    buttons.push(
      <Button
        key="reject"
        variant="destructive"
        onClick={() => handleAction(() =>
          respondMutation.mutateAsync({ id: quoteId, data: { response: "rejected" } })
        )}
        disabled={respondMutation.isPending}
      >
        Record: Rejected
      </Button>
    );
  }

  const statusCfg = STATUS_CONFIG[status];

  return (
    <div className="flex items-center gap-3 flex-wrap">
      <Badge className={statusCfg.className}>{statusCfg.label}</Badge>
      {buttons}
    </div>
  );
}

import { useQuote } from "@/hooks/useQuotes";
import { useBoqItems } from "@/hooks/useBoqs";
import { QuoteActions } from "./QuoteActions";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { ArrowLeft, Download } from "lucide-react";
import { api } from "@/lib/api";
import { getAccessToken } from "@/lib/auth";

interface QuoteDetailProps {
  quoteId: string;
  onBack: () => void;
}

const TIMELINE_STEPS = ["draft", "pending_approval", "approved", "sent", "accepted"] as const;

function StatusTimeline({ status }: { status: string }) {
  const statusIndex = TIMELINE_STEPS.indexOf(status as typeof TIMELINE_STEPS[number]);
  const isRejected = status === "rejected";
  const currentIndex = isRejected ? -1 : statusIndex;

  return (
    <div className="flex items-center gap-2 flex-wrap">
      {TIMELINE_STEPS.map((step, idx) => {
        const isActive = idx === currentIndex;
        const isCompleted = idx < currentIndex;
        return (
          <div key={step} className="flex items-center gap-2">
            <div
              className={`flex items-center justify-center w-6 h-6 rounded-full text-xs font-bold ${
                isActive
                  ? "bg-primary text-primary-foreground"
                  : isCompleted
                    ? "bg-primary/20 text-primary"
                    : "bg-muted text-muted-foreground"
              }`}
            >
              {idx + 1}
            </div>
            <span className={`text-xs ${isActive ? "font-semibold" : "text-muted-foreground"}`}>
              {step.replace(/_/g, " ")}
            </span>
            {idx < TIMELINE_STEPS.length - 1 && (
              <div className={`w-6 h-px ${isCompleted ? "bg-primary" : "bg-muted"}`} />
            )}
          </div>
        );
      })}
      {isRejected && (
        <Badge className="bg-red-100 text-red-800 ml-2">Rejected</Badge>
      )}
    </div>
  );
}

export function QuoteDetail({ quoteId, onBack }: QuoteDetailProps) {
  const { data: quote, isLoading } = useQuote(quoteId);
  const { data: itemsData } = useBoqItems(quote?.boq_id ?? "");

  if (isLoading) return <div className="p-4 text-muted-foreground">Loading quote...</div>;
  if (!quote) return <div className="p-4 text-destructive">Quote not found</div>;

  const items = itemsData?.items ?? [];

  const handleDownloadPdf = async () => {
    try {
      const response = await fetch(`/api/quotes/${quoteId}/pdf`, {
        headers: { Authorization: `Bearer ${getAccessToken()}` },
      });
      if (response.ok) {
        const blob = await response.blob();
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = `quote-${quoteId}.pdf`;
        a.click();
        URL.revokeObjectURL(url);
      }
    } catch {
      console.error("PDF download failed");
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="icon" onClick={onBack}>
          <ArrowLeft className="h-4 w-4" />
        </Button>
        <div className="flex-1">
          <h2 className="text-xl font-bold">Quote v{quote.version_number}</h2>
        </div>
        <Button variant="outline" onClick={handleDownloadPdf}>
          <Download className="mr-2 h-4 w-4" />
          PDF
        </Button>
      </div>

      <QuoteActions quoteId={quoteId} status={quote.status} />

      <Card>
        <CardHeader>
          <CardTitle>Status Timeline</CardTitle>
        </CardHeader>
        <CardContent>
          <StatusTimeline status={quote.status} />
        </CardContent>
      </Card>

      <div className="grid grid-cols-2 gap-6">
        <Card>
          <CardHeader>
            <CardTitle>Details</CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label className="text-muted-foreground">Status</Label>
                <p>{quote.status.replace(/_/g, " ")}</p>
              </div>
              <div>
                <Label className="text-muted-foreground">Created By</Label>
                <p>{quote.created_by_name ?? "—"}</p>
              </div>
              <div>
                <Label className="text-muted-foreground">Valid Until</Label>
                <p>{quote.valid_until ? new Date(quote.valid_until).toLocaleDateString() : "—"}</p>
              </div>
              <div>
                <Label className="text-muted-foreground">Validity Days</Label>
                <p>{quote.validity_days}</p>
              </div>
              <div>
                <Label className="text-muted-foreground">Approved By</Label>
                <p>{quote.approved_by_name ?? "—"}</p>
              </div>
              <div>
                <Label className="text-muted-foreground">Sent At</Label>
                <p>{quote.sent_at ? new Date(quote.sent_at).toLocaleString() : "—"}</p>
              </div>
            </div>
            {quote.terms && (
              <div>
                <Label className="text-muted-foreground">Terms & Conditions</Label>
                <p className="text-sm whitespace-pre-wrap">{quote.terms}</p>
              </div>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Totals</CardTitle>
          </CardHeader>
          <CardContent className="space-y-2">
            <div className="flex justify-between text-sm">
              <span>Subtotal</span>
              <span>₹{quote.subtotal.toLocaleString()}</span>
            </div>
            <div className="flex justify-between text-sm">
              <span>Markup ({quote.markup_percent}%)</span>
              <span>₹{quote.markup_amount.toLocaleString()}</span>
            </div>
            <div className="flex justify-between text-sm">
              <span>Tax ({quote.tax_percent}%)</span>
              <span>₹{quote.tax_amount.toLocaleString()}</span>
            </div>
            <div className="flex justify-between font-semibold border-t pt-2">
              <span>Total</span>
              <span>₹{quote.total_amount.toLocaleString()}</span>
            </div>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Line Items</CardTitle>
        </CardHeader>
        <CardContent>
          {items.length === 0 ? (
            <p className="text-muted-foreground text-sm">No items loaded.</p>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Line</TableHead>
                  <TableHead>Description</TableHead>
                  <TableHead>Unit</TableHead>
                  <TableHead className="text-right">Qty</TableHead>
                  <TableHead className="text-right">Rate</TableHead>
                  <TableHead className="text-right">Amount</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {items.map((item) => (
                  <TableRow key={item.id}>
                    <TableCell className="font-mono">{item.line_number}</TableCell>
                    <TableCell>{item.description}</TableCell>
                    <TableCell>{item.unit}</TableCell>
                    <TableCell className="text-right">{item.quantity}</TableCell>
                    <TableCell className="text-right">₹{item.rate.toLocaleString()}</TableCell>
                    <TableCell className="text-right">₹{item.amount.toLocaleString()}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

